CREATE TABLE IF NOT EXISTS tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), project_id UUID REFERENCES projects(id), contact_id UUID REFERENCES contacts(id), monitoring_alert_id UUID, ticket_number TEXT NOT NULL UNIQUE, subject TEXT NOT NULL, description TEXT, priority TEXT NOT NULL DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'open', assignee_user_id UUID REFERENCES users(id), internal_notes TEXT, sla_due_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, created_by_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ticket_comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id UUID NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, author_user_id UUID REFERENCES users(id), body TEXT NOT NULL, customer_visible BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
